-- One self-contained record following DocumentIngestSchema.
CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES ($CODEx3070026b4bb1$doc_the_patent_design_and_trade_mark_act_2022_1965__2022_patent_and_design_act_pdf$CODEx3070026b4bb1$,$CODExf7e9faea3ae4$The Patent, Design and Trade Mark Act, 2022 (1965)$CODExf7e9faea3ae4$,NULL,$CODEx76f3b5a7170a$act$CODEx76f3b5a7170a$,2022,1965,23,$CODEx20a290fc4182$[{"tier": 1, "nodeType": "preamble", "identifier": "Preamble", "title": "Introductory matter", "content": "www.lawcommission.gov.np \nThe Patent, Design and Trade Mark Act, 2022 (1965) \nDate of Authentication and publication \n14 Bhadra 2022. (august 30 , 1965 A.D.) \nAmendement Date of Amendement", "children": []}, {"tier": 1, "nodeType": "section_group", "identifier": "Sections", "title": "Sections", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "First Amendment. Kartik 1,2044 (October 18, 1987 )", "content": null, "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Act Made to Amend Some Nepal Acts Relating to Export and Import", "content": "and Intellectual Property, 2063 (2006) 2063.8.8 (November 24, 2006) \nPreamble: Whereas it is necessary to update the legal arrangements in respect to \npatents, designs and trade-marks for the convenience and economic benefit of the \ngeneral Public, \nBe it enacted by, His Majesty King Mahendra Bir Bikram Shah Dev on the aid and \nadvice of the National Panchayat.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 1", "title": "Chapter 1", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "1", "title": "Short Title Extent and Commencement : (1) This Act may be called", "content": "\"Patent, Design and Trade Mark Act, 1965 \", \n(2) It shall be applicable throughout the Kingdom of Nepal. \n(3) It shall come into force immediately.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "2", "title": "Definitions : Unless the subject or the context otherwise requires in this Act :", "content": "(a)\t \"patent\" means any useful invention relating to a new method of \nprocess or manufacture, operation or transmission of any material \nor a combination of materials, or that made on the basis of a \nnew theory or formula. \n(b)\t \"Design\" means the form or shape of any material manufactured \nin any manner. \n♣ (c)\t \"Trade-mark\" means word, symbol, or picture or a combination \nthereof to be used by any firm, company or individual in its \n♣ Amendment by the first amendment \n1\n \n \n  \n             \n    \n            \n            \n     \n            \n               \n             \n   \n  \n              \n                \n  \n                     \n             \n                \n    \n           \n                 \n            \n          \n \n  \n                    \n                                                   \n        \n                     \n    \n                       \n    \n \nwww.lawcommission.gov.np \nproducts or services to distinguish them with the product or \nservices of others. \n(d)\t \"Department\" means the department prescribed by Government of \nNepal by notification in the Nepal Gazette and the Department of \nIndustry unless so prescribed. \n(e)\t \"Schedule\" means the schedule to this Act. \n� (f) \"Prescribed or as prescribed\" means prescribed as prescribed in \nthe Rules framed or orders issued under this Act.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 2", "title": "Chapter 2", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "3", "title": "ACQUISITION OF PATENT RIGHTS : (1) A person desirous of", "content": "obtaining right over any patent shall register such patent in his/her name under \nthis Act. \n∇ (2) No one shall copy or use or cause to use in the name of the others \nwithout transforming the ownership or written permission pursuant to Section \n21d, the patent registered in the name of any person pursuant to this Act . \n(3) ∝ .............", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "4", "title": "APPLICATION FOR ACQUIRING RIGHT OVER PATENT : (1) A", "content": "person desirous of having any patent registered in his/her name shall submit to \nthe Department an application as specified in Schedules 1 (a), containing the \nparticulars mentioned hereunder, along with all available evidence in his/her \npossession: \n(a)\t Name address and occupation of the parson inventing the \n� Inserted by the first amendment \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n∝ Deleted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n2\n \n \n  \n   \n                   \n            \n                  \n                      \n                \n                 \n            \n            \n                 \n                \n                   \n                 \n          \n                 \n                 \n                  \n   \n  \n            \n               \n \n                 \n    \n                \n            \n        \n                                                   \n      \n       \nwww.lawcommission.gov.np \npatent. \n(b)\t If the applicant him/herself is not the inventors, how and in what \nmanner he/she acquired title thereto from the inventor. \n(c)\t Process of manufacturing, operating or using the patent. \n(d)\t The theory or formula if any, on which the patent is based. \n(2) Along with the application pursuant Sub- Section (1), applicant \nshall also submit map and ♣ drawings along with particulars , of the patent, \nas well as the fee specified in Schedule 3(1) (a).", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "5", "title": "INVESTIGATION BY DEPARTMENT : (1) On receipt of application", "content": "submitted under Section 4, the Department shall, on the advice of experts if so \nconsidered necessary, conduct all investigation or study to ascertain whether \nthe patent investigations in the application is a new invention or not, and \nwhether it is useful to the general public or not, and thereafter decide whether \nor not to register such patent. \n(2) In case the Department concludes that any patent should not be \nregistered in the circumstances mentioned in Section 6, it shall give a notice to \nthe applicant to the effect that the patent cannot be registered according to \nhis/her application. \n(3) ……..\n�", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "6", "title": "CIRCUMSTANCES IN WHICH PATENTS CANNOT BE REGISTERED :", "content": "(1) The Department shall not register any patent under this Act in the following \ncircumstances:­\n(a)\t In case the patent is already registered in the name of any \nother person, or \n(b)\t In case the applicant him/herself is not the inventor of the \npatent sought to be so registered nor has acquired rights \nover it from the original inventor, or \n♣ Amendment by the first amendment \n� Deleted by the first amendment \n3\n \n \n  \n                    \n             \n     \n              \n            \n     \n          \n            \n        \n                \n              \n  \n             \n                \n           \n              \n                    \n               \n                 \n          \n                 \n                \n    \n                  \n                      \n                   \n  \n                                                   \n       \nwww.lawcommission.gov.np \n(c)\t In case the patent sought to be registered is likely to \nadversely effect the public health, conduct or morality or \nthe national interest, or \n(d)\t In case it is contradictory to the prevailing laws (the \nregistration of the patent) will constitute a contravention \nof existing Nepal law. \nProvided that noting contained in Clause (a) shall be \ndeemed to have prejudiced to update transfer of the \nregistration of any patent under Section 9. \n(2) In the circumstances mentioned in Sub-Section (1), the \nDepartment may cancel the registration of any patent which had been \nregistered. \nProvided that the Department shall, before cancelling the registration of any \npatent, provide reasonable opportunity to the patentee to show the cause, if \nany, why the registration of this patent should not be cancelled. \n7.\t \nREGISTRATION OF PATENT : (1) On receipt of applications filed \nunder Section 4 for registration of a patents, the Department shall, after \ncompleting necessary investigations under Section 5 issue a registration \ncertificate in a format as specified in Schedule 2 (a) to the applicant, except in \nthe circumstance mentioned in Section 6. \n(2) For obtaining the certificate mentioned in Sub-Section (1), the \napplicant shall pay the registration fees as to the department specified in \nschedule 3 (1) (b). \n� 7A. Registered patents to be published : (1) Patents registered under this Act, \nother than those which must be kept secret in the national interest, shall be \npublished by the Department in the Nepal Gazette for the information of the \npublic. \n� Inserted by the first amendment \n4\n \n \n  \n                 \n                   \n              \n                     \n                         \n            \n                   \n            \n                     \n                         \n              \n                 \n                   \n                 \n               \n \n    \n                \n              \n                   \n        \n                   \n                 \n            \n                                                   \n      \n                       \n   \n                        \n   \nwww.lawcommission.gov.np \n(2) In case anybody desires to see or copy the particulars, maps, \nor drawings of a patent published under Sub-Section (1), one may be \nallowed to do so after paying the fees prescribed by the Department. \n(3) In case anyone has any objection to such a patent, one may \nfile a complaint with the Department within a period of 35 days from the \ndate of seeing or copying the patent under Sub-Section 92). \n(4) In case any complaint is received under Sub-Section (3), \nthe Department shall take necessary Action after conducting inquiries \n♣ 8.\t TERM OF PATENT : (1) The title of the patentee to the patent shall be \nvalid only for a period of seven years from the date of registration \nthereof under Section 7, except when it is renewed under Section 23 B. \n(2) Notwithstanding, anything contained in Sub-Section (1),in the case \nof patent registered before the commencement of this Section, the term \nfixed according to the provision in force at the time of registration thereof shall \nbe valid After the expiry of that term, the patent must be renewed under Section \n23B. \n∝9.\t ..........", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "10", "title": "SUBMISSION OF DESIGN OR MODEL OF PATENT TO", "content": "GOVERNMENT ARCHIVES : The patentee shall submit to the National \nArchive also a copy of the design or model of the article manufactured \naccording to the patent registered under this Act. \n∇ 11.\t Penalty for violation of Section 3 : A person, who commits any of the acts, \nshall be fined as per gravity of offense by the order of the Department and the \ngoods or commodities related to the offense shall be confiscated : \n♣ Amendment by the first amendment. \n∝ Deleted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n5\n \n \n  \n              \n          \n               \n             \n         \n  \n  \n                 \n                       \n        \n                     \n             \n                    \n            \n                  \n                    \n                \n                   \n                \n                  \n       \n               \n             \n                  \n               \n             \n                                                   \n                    \n   \nwww.lawcommission.gov.np \n(a)\t A fine of upto Five Hundred Thousand Rupees for committing an \noffense mentioned in Sud-section 2 of Section 3 . \n(b)\t A fine of upto Two Hundred and Fifty Thousand (Two lac fifty \nthousand ) Rupees for committing an attempt or abetment of an offense \nmentioned in Sud-section (2) of Section 3 .", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 3", "title": "Chapter 3", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "12", "title": "ACQUISITION OF TITLE TO DESIGN : (1) A person may acquire", "content": "title under this Act to the design of any article manufactured or caused to be \nmanufactured upon registration under Section 14. \n∇ (2) No one shall copy or use or cause to use in the name of the others \nwithout transforming the ownership or written permission pursuant to Section \n21d, the design registered in the name of any person pursuant to this Act .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "13", "title": "APPLICATION FOR REGISTRATION OF DESIGN : (1) A person", "content": "desirous to register the design of any article manufactured or caused to be \nmanufactured under Section 14, shall submit to the Department, an \napplication in a formals as specified in Schedule 1 (b), together with four \ncopies of such design and maps, and drawings and particulars thereof. \n(2) The person submitting an application under Sub-Section (1) shall \npay, along with the application, the application fee to the department \nspecified in Schedule 3 (2) (a),. \n14.\t \nREGISTRATION OF DESIGN : (1) On receipt of the application filed by \nany person under Section 13, the Department shall register the design in the \nname of the applicant and issue a certificate as mentioned in Schedule 2(b). \nProvided that in case such design hurts the prestige of any individual or \ninstitution or adversely affects the public conduct or morality, or undermines the \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n6\n \n \n  \n                     \n               \n                 \n              \n    \n                  \n              \n      \n             \n                \n            \n                     \n                \n             \n           \n              \n                   \n              \n              \n   \n \n \n \n                                                   \n        \n       \n                     \n   \n                    \n   \n \nwww.lawcommission.gov.np \nnational interest, or in case such design has already been registered in the \nname of any other person, it shall not be registered under this-Section. \n(2) For obtaining the certificate mentioned in Sub-Section (1), the \napplicant shall pay a design registration fee as prescribed in Schedule 3 (2) (b), \nto the department. \n(3) In case the Department is satisfied that there exists any \ncircumstance as mentioned in the provision of Sub-Section (1), it may cancel \nthe registration of any design. \nProvided that the department shall, before cancelling the registration of such \ndesign, provide reasonable opportunity to the design- holder to show case if \nany, why the registration of his/her design should not be cancelled. \n� 14A. Term of Design. The title of the person in whose name a design has been \nregistered under Section 14 shall remain valid for a period of five years from \nthe date of registration thereof, except when it is renewed under Section 23B. \n15.\t \nPUNISHMENT FOR CONTRAVENTION OF SECTION 12 : In case a \nperson, contravenes the provisions or Sub-Section (2) of Section 12, or operates \na design invalidated the Department, may be ♣ punished with a fine not \nexceeding ∇ Fifty thousand Rupees, and articles and goods connected with such \noffense shall be confiscated on the order of the Department, ™ as per the gravity \nof offense. \n� Inserted by the first amendment \n♣ Amendment by the first amendment \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n™\t Inserted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n7\n \n \n  \n   \n  \n                      \n               \n     \n                      \n          \n              \n  \n            \n                    \n               \n               \n         \n             \n           \n                  \n                   \n                 \n            \n              \n           \n          \n               \n                                                   \n                       \n    \n                      \n   \n \nwww.lawcommission.gov.np", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 4", "title": "Chapter 4", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "16", "title": "Acquisition of title to trade marks : : (1) A person may acquire, under", "content": "this Act, title to the trade-mark of his business, upon registration in the \ndepartment under Section 18. \n∇ (2) No one shall copy or use or cause to use in the name of the others \nwithout transforming the ownership or written permission pursuant to Section \n21d, the trademark registered in the name of any person pursuant to this Act.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "17", "title": "APPLICATION FOR REGISTRATION OF TRADEMARK : (1) A", "content": "person desirous to register the trademark of his business registered under \nSection 18 shall submit to the Department an application in a format as \nspecified in Schedule 1(c), along with four specimen of such trade-marks, \nshall conduct necessary investigation and provide sufficient opportunity to \ndefend him/her self and also conduct further inquiry based on the dense made \nand if finds it appropriate to register it . \n(2) The person submitting application under Sub-section (1), \nshall pay an application fee to the department as specified in Schedule 3(3) (a). \n18. \nREGISTRATION OF TRADEMARK : (1) In case any person files an \napplication under Section 17 for registration of trademark, the department shall \nregister such trademark in the name of the applicant the specimen form \nindicated in Schedule 2 (c), \n™ shall conduct necessary investigation and provide \nsufficient opportunity to defend him/herself and also conduct further inquiry \nbased on the cense made and if finds it appropriate to register it . \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n™ Inserted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n8\n \n \n  \n                   \n              \n                 \n               \n             \n                   \n                   \n  \n                     \n                         \n    \n                      \n              \n             \n              \n                  \n                 \n      \n                \n               \n              \n               \n      \n                  \n         \n                 \n                      \n          \n      \n                                                   \n       \nwww.lawcommission.gov.np \nProvided that in case it is felt such trade-mark may hurt the prestige of any \nindividual or institution or adversely affect the public conduct or morality or \nundermine the national interest or the reputation of the trade-mark of any \nother person, or in case such trade-mark is found to have already been \nregistered in the name of another person, it shall not be registered \n(2) To obtain a certificate as mentioned in Sub-Section (1), the \napplicant shall pay registration fees as specified in Schedule 3 (3) (b) to \nthe Department. \n(3) The Department may cancel the registration of any trade-mark, \nif it is satisfied that any of the circumstance prescribed in the provision of \nSub-Section (1) exists. \nProvided that the Department shall, before cancelling the registration of a \ntrademark provide a reasonable opportunity to the holder of the trademark to \nshow cause if any, why his/her trademark should not be cancelled. \n� 18A. Classification of Goods and Services for Trade-Mark Registration : \n(1) For the purpose of registering trade-marks related to any goods or \nservices, Government of Nepal may classify such goods or services by a \nnotification in the Nepal Gazette . \n(2) Separate application shall be submitted to register trade­\nmarks of goods or services placed in different categories. \n(3) The trade-mark registered for goods or services in one category \nunder Sub-section (1) may be registered for goods or services under another \ncategory if it so falls . \n� 18B. Prohibition to Use Trade-marks : No trade-mark may be used as a \nregistered trade-mark without registering it at the Department. \n� 18C. Time Limit for Use of Trade-marks : In case a trade-mark registered at \nthe Department is not brought into use within one year from the date of \nregistration thereof, the department shall conduct necessary inquiries and \ncancel such registration. \n� Inserted by the first amendment \n9\n \n \n  \n                \n                 \n             \n  \n             \n                \n                 \n               \n            \n               \n \n  \n  \n                 \n                \n               \n    \n    \n           \n                 \n                                                   \n        \n       \n                      \n   \n                       \n   \n        \n \n \n \n \n \n \nwww.lawcommission.gov.np \n� 18D. Term of Trade-Marks : The title of the person in whose name a trade-mark \nhas been registered under Section 18 shall remain valid for a period of seven \nyears from the date of registration thereof, except when it is renewed under \nSection 18. \n♣ 19.\t PUNISHMENT FOR ILLEGAL USE OF TRADE-MARKS : In case \nany one who, violates Sub-Section (2) of Section 16, or brings into use a trade­\nmark which has been cancelled under Sub-section (3) of Section 18, or \nviolates Section 18B, may be punished with a fine not exceeding is \n∇ One \nHundred Thousand Rupees and articles and goods connected with such offense \nconfiscated on the orders of the Department ™ as per the gravity of offense. \n.", "children": []}]}, {"tier": 1, "nodeType": "chapter", "identifier": "Chapter 5", "title": "Chapter 5", "content": null, "children": [{"tier": 2, "nodeType": "section", "identifier": "20", "title": "Right to appoint Attorney : A person may appoint an attorney or � legal", "content": "practitioner for to take any Action so required under this Act, and all Actions \ntaken ♣ by such attorney or legal practitioner shall be deemed to have been taken \nby him/herself . \n21\t ……. �\n� 21A. Publication of Registered Designs and Trade-Marks :(1) The \nDepartment shall publish the designs registered under Section 14 and the \n� Inserted by the first amendment \n♣ Amendment by the first amendment \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n™\t Inserted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n� Deleted by the first amendment \n10\n \n \n  \n             \n          \n                      \n              \n                 \n          \n                      \n                  \n             \n          \n           \n             \n                \n             \n           \n                 \n             \n        \n                 \n                \n             \n          \n              \n            \n    \n                                                   \n       \n                      \n  \n                    \n   \nwww.lawcommission.gov.np \ntrade-marks registered under Section 18, as well as particulars of their renewal \nor cancellation, for the information of the public. \n(2) Any one who has any objection to the particulars published under \nSub-Section (1) may file a complaint to the department within a period of 35 \ndays from the date of such publication . The Department shall take necessary \nActions after holding inquiries into such complaints. \n� 21B. Title Not to be valid Unless Registered in Nepal : The title to any \npatent, design or trade-mark registered in a foreign country shall not be valid \nin Nepal unless it is registered in Nepal by the concerned person. \n� 21C. Registration of Foreign patents, Designs and Trade-Marks : The \nDepartment may register patents, designs and trade- marks registered in foreign \ncountries without conducting any enquiries if an application is filed for their \nregistration along with certificates of its registration in a foreign country ™ and \nthe Department shall provide the facility of pursuant to the Paris Convention for \nthe Protection of Industrial Property 1883 to the registration holder. \n∇ 21D. Transfer of ownership or approval for use of patent, Design or Trade :(1) \nThe owner of the patent, Design or Trademark may transfer the ownership or \nprovide approval in writing for its use. \n(2) In case it is so intended to transfers the ownership or to provide or \nreceived the approval for the use of patent, Design or Trademark pursuant to \nSub-Section (1), both the persons shall file a joint application, stating the facts \naccordingly before the Department accompanied by the prescribed fees . \n(3) If an application pursuant to Sub-section (2) is received , the \nDepartment may transfer the ownership or provide approval of use for such \npatent, design or trademark. \n� Inserted by the first amendment\n \n™ Inserted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual Property,\n \n2063 (2006) \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n11\n \n \n  \n              \n          \n                \n           \n            \n              \n                 \n           \n    \n     \n           \n                  \n                    \n                \n               \n                \n   \n                    \n                 \n               \n       \n                 \n                      \n                                                   \n      \n                      \n    \n       \n \n                    \n   \nwww.lawcommission.gov.np \n(4) If the ownership of the patent, design or trademark is transferred \npursuant to Sub-section (3), the name of receiving person. \n(5) If the approval for use is provided pursuant to Sub-section (2) the \nDepartment shall maintain the register-book and certificate laying in the office \naccordingly and also issue a note for the same to the receiver.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "22", "title": "Maintain Register by the Department : The Department shall maintain", "content": "separate register of patents, designs and trade-marks, indicating therein \nregistration or cancellation thereof under this Act. \n♣ 23.\t ∝ ..................\n \n� 23A. ∝ ................\n \n� 23B. Procedure Relating to Renewal of Patents, Designs and Trade-Marks : \n(1) A patent, design or trade-marks holder shall renew the patent, design or \ntrade-mark within a period of 35 days from the date of expiry of the term for \nwhich he is entitled to use the patent, design or trade-mark under Section 8, \nSection 14A or Section 18D by submitting an application in a format mentioned \nin Schedule 2 (d), 2(e) and 2(f) respectively and paying the fee motioned in \nSchedule 3. \n(2) Renewal may be made by paying a fine of \n∇ One Thousand Rupees \nwithin six months after the expiry of the time-limit for the same pursuant Sub-\nSection (1). In case it is not so renewed registration of the patent, design and \ntrade-mark shall automatically cancelled . \n(3) Notwithstanding anything contained in Sub-Section (1) and (2), a \npatent may be renewed not more than Twice for a period of Seven years at a \n♣ Amendment by the first amendment.\n \n∝ Deleted by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual\n \nProperty, 2063 (2006) \n� Inserted by the first amendment \n∇ Amended by the Act Made to Amend Some Nepal Acts Relating to Export and Import and Intellectual \nProperty, 2063 (2006) \n12\n \n \n  \n                  \n               \n                 \n              \n             \n                \n                \n                   \n              \n                  \n                \n             \n             \n             \n                 \n                  \n     \n                 \n               \n                  \n \n \n \n \n \n                                                   \n      \n       \n      \nwww.lawcommission.gov.np \ntime, a design not mode than twice for a period of five years at a time, and a \ntrade-mark any number of times for a period of seven years at a time.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "24", "title": "Copy of Certificate : In case the certificate of registration of any patent,", "content": "design or trade-mark is lost, a copy thereof may be obtained from the \nDepartment on payment of a fee as ♣ prescribed .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "25", "title": "Compensation : In case a person whose patent, design or trademark has been", "content": "registered under this Act, suffers any losses as a result of violation of the \nprovisions of this Act by any others person in respect to the patent, design or \ntrade-mark, the Department may order to ==== amount actually by the title \nholder from such offender in the form of compensation.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "26", "title": "Deemed to be r", "content": "egistered under this Act : The patents, designs and trade­\nmarks registered prior to the commencement of this Act under the patent, design \nand trademarks law enacted in 1936, shall be deemed to have been registered \nunder this Act, with effect from the date of its commencement. \n� 26A. Power to Alter the Rates of Fees : Government of Nepal may make \nalterations in the amount of fees prescribed in Schedule 3 by a notification in \nthe Nepal Gazette .", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "27", "title": "May Appeal : Any person not satisfied with the order issued by the Department", "content": "under this Act may file an \n�appeal with the Appellate Court within 35 days.", "children": []}, {"tier": 2, "nodeType": "section", "identifier": "28", "title": "REPEAL : The Patent, Design and Trademark law of 1936 has been repealed.", "content": "♣ Amendment by the first amendment \n� Inserted by the first amendment \n� Amendment by justice administrative act,2048 \n13\n \n \n  \n   \n         \n \n \n  \n                    \n               \n                     \n                \n                           \n \n                                      \n                                   \n   \n \n \n \n \n \n \n \n \n \n \n                                                   \n      \nwww.lawcommission.gov.np \n♣ S